WITH upsert AS
(
    UPDATE sch11_ipo_company
       SET sch11_interest_yn = #{interestYn}
     WHERE sch11_ipo_id      = #{ipoId}
       AND sch11_company_id  = #{companyId}
 RETURNING *
)
INSERT INTO sch11_ipo_company
       ( sch11_ipo_company_id, sch11_ipo_id, sch11_company_id, sch11_interest_yn )
SELECT f_create_seq(), #{ipoId}, #{companyId}, #{interestYn}
 WHERE NOT EXISTS ( SELECT * FROM upsert )

