INSERT INTO sys99_print
       ( sys99_print_id, sys99_company_id, sys99_person_id, sys99_window_class_nm, sys99_group_id
       , sys99_string01, sys99_string02, sys99_string03
       , sys99_date01, sys99_date02, sys99_date03, sys99_date04, sys99_date05, sys99_date06
       , sys99_string04, sys99_long01, sys99_text01, sys99_string05 )
VALUES ( #{printId}, #{companyId}, #{personId}, #{windowClassName}, #{groupId}
       , #{row.interestName}, #{row.marketName}, #{row.itemName}
       , #{row.demandStartDate}, #{row.demandCloseDate}, #{row.subscriptionStartDate}, #{row.subscriptionCloseDate}, #{row.payDate}, #{row.listDate}
       , #{row.priceBracket}, #{row.price}, #{row.note}, '' )
